const item = $input.item.json;
const text = (item.text || item.snippet || '').replace(/\s+/g, ' ');
const subject = item.subject || '';
const combined = subject + ' ' + text;
const paymentMatch = combined.match(/\$\s?([0-9]+(?:[.,][0-9]{2})?)|(?:USD|CAD|HKD|RMB|￥|€|£)\s?([0-9]+(?:[.,][0-9]{2})?)|([0-9]+(?:[.,][0-9]{2})?)\s?(?:USD|CAD|HKD|RMB|€|£)/i);
let payment = null;
if (paymentMatch) { payment = paymentMatch[1] || paymentMatch[2] || paymentMatch[3]; }
const nameMatch = combined.match(/(?:name|名稱|姓名|customer)[\s:：]+([A-Za-z一-鿿][A-Za-z0-9一-鿿 ]{1,40}?)(?:[\s,，.。]|job|code|pickup|payment|$)/i);
const codeMatch = combined.match(/(?:job|code|order|訂單|編號|#)[\s:：#]*([A-Za-z0-9][A-Za-z0-9\-]{2,20})/i);
const pickupMatch = combined.match(/(?:pickup|取貨|取件)[\s:：]+([0-9]{1,2}[\/:\- ][0-9]{1,2}[\/:\- ][0-9]{2,4}(?:[ T][0-9]{1,2}:[0-9]{2}(?::[0-9]{2})?)?|[0-9]{4}[\-/.][0-9]{1,2}[\-/.][0-9]{1,2}(?:[ T][0-9]{1,2}:[0-9]{2})?)/i);
return {
  json: {
    emailId: item.id,
    from: item.from,
    subject: subject,
    payment: payment,
    name: nameMatch ? nameMatch[1].trim() : null,
    code: codeMatch ? codeMatch[1].trim() : null,
    pickupTime: pickupMatch ? pickupMatch[1].trim() : null,
    body: text
  }
};

const items = $input.all();
if (items.length === 0) { return []; }
const lines = ['🖨️ New print job payments (' + items.length + '):', ''];
for (const it of items) {
  const d = it.json;
  lines.push('💰 $' + (d.payment || '?'));
  lines.push('👤 ' + (d.name || '?'));
  lines.push('🔖 ' + (d.code || '?'));
  lines.push('⏰ ' + (d.pickupTime || '?'));
  lines.push('📧 ' + (d.subject || ''));
  lines.push('');
}
return [{ json: { text: lines.join('\n'), count: items.length } }];
